import numpy as np
from collections import deque
def f(t):
    t=np.array(t); a=t.copy()
    vals,cnt=np.unique(t,return_counts=True)
    bg=vals[cnt.argmax()]
    H,W=a.shape
    vis=np.zeros_like(a,dtype=bool); q=deque()
    # seed border cells
    for c in range(W):
        for nr in [0,H-1]:
            if t[nr][c]==bg: vis[nr][c]=True; q.append((nr,c))
    for r in range(H):
        for nc in [0,W-1]:
            if t[r][nc]==bg: vis[r][nc]=True; q.append((r,nc))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and not vis[nr][nc] and t[nr][nc]==bg:
                vis[nr][nc]=True; q.append((nr,nc))
    return [[2 if t[r][c]!=bg and not vis[r][c] else t[r][c] for c in range(W)] for r in range(H)]
