G=load()

def solve(g,verbose=False):
    a=np.array(g); R,C=a.shape
    cnt=Counter(a.flatten().tolist()); bg=cnt.most_common(1)[0][0]
    fg=[v for v,_ in cnt.items() if v!=bg][0]
    rs=[r for r in range(R) for c in range(C) if a[r,c]==fg]
    cs=[c for r in range(R) for c in range(C) if a[r,c]==fg]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    out=a.copy()
    def mark(r,c):
        if 0<=r<R and 0<=c<C and out[r,c]==bg: out[r,c]=2
    # horizontal: for each row, pairs of fg cells -> fill between
    for r in range(r0,r1+1):
        s=sorted(c for c in range(c0,c1+1) if a[r,c]==fg)
        for i in range(len(s)-1):
            for c in range(s[i]+1,s[i+1]): mark(r,c)
    # vertical: for each column
    for c in range(c0,c1+1):
        s=sorted(r for r in range(r0,r1+1) if a[r,c]==fg)
        for i in range(len(s)-1):
            for r in range(s[i]+1,s[i+1]): mark(r,c)
    return [[int(v) for v in row] for row in out.tolist()]

